"use client";

import * as React from "react";
import { AlertDialog as AlertDialogPrimitive } from "@base-ui/react/alert-dialog";

import { cn } from "@/lib/utils";
import { buttonVariants } from "@/components/ui/button";

// Base UI accepts a state function for className; these wrappers merge it with
// cn(), so they take a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Margin AlertDialog root: a modal that waits for a decision. */
const AlertDialog = AlertDialogPrimitive.Root;

/** The control that opens the alert dialog. */
const AlertDialogTrigger = AlertDialogPrimitive.Trigger;

/** Moves the alert dialog to the end of the document body. */
const AlertDialogPortal = AlertDialogPrimitive.Portal;

/** Margin alert scrim: a soft grey veil; a click on it does not dismiss. */
const AlertDialogOverlay = React.forwardRef<
  HTMLDivElement,
  WithClassName<AlertDialogPrimitive.Backdrop.Props>
>(({ className, ...props }, ref) => (
  <AlertDialogPrimitive.Backdrop
    ref={ref}
    data-slot="alert-dialog-overlay"
    className={cn(
      "fixed inset-0 z-50 bg-(--scrim)",
      "transition-opacity duration-base ease-(--ease-out)",
      "data-[starting-style]:opacity-0 data-[ending-style]:opacity-0",
      className,
    )}
    {...props}
  />
));
AlertDialogOverlay.displayName = "AlertDialogOverlay";

/**
 * Margin alert window: a white panel with the large corner, 28rem wide at
 * most. It has no close button, so the reader answers with a button.
 */
const AlertDialogContent = React.forwardRef<
  HTMLDivElement,
  WithClassName<AlertDialogPrimitive.Popup.Props>
>(({ className, ...props }, ref) => (
  <AlertDialogPortal>
    <AlertDialogOverlay />
    <AlertDialogPrimitive.Popup
      ref={ref}
      data-slot="alert-dialog-content"
      className={cn(
        "fixed inset-x-4 top-1/2 z-50 mx-auto grid max-w-md -translate-y-1/2 gap-4",
        "rounded-3xl bg-popover p-5 text-popover-foreground shadow-(--shadow-overlay) outline-none",
        "transition-[opacity,scale] duration-base ease-(--ease-out)",
        "data-[starting-style]:scale-97 data-[starting-style]:opacity-0",
        "data-[ending-style]:scale-97 data-[ending-style]:opacity-0",
        className,
      )}
      {...props}
    />
  </AlertDialogPortal>
));
AlertDialogContent.displayName = "AlertDialogContent";

/** The question block at the top of the alert. */
const AlertDialogHeader = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    data-slot="alert-dialog-header"
    className={cn("flex flex-col gap-1 text-start", className)}
    {...props}
  />
);
AlertDialogHeader.displayName = "AlertDialogHeader";

/** The answer row: stacked on a phone, in a row at the end from the small breakpoint. */
const AlertDialogFooter = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    data-slot="alert-dialog-footer"
    className={cn("flex flex-col-reverse gap-2 sm:flex-row sm:justify-end", className)}
    {...props}
  />
);
AlertDialogFooter.displayName = "AlertDialogFooter";

/** The alert question in semibold. */
const AlertDialogTitle = React.forwardRef<
  HTMLHeadingElement,
  WithClassName<AlertDialogPrimitive.Title.Props>
>(({ className, ...props }, ref) => (
  <AlertDialogPrimitive.Title
    ref={ref}
    data-slot="alert-dialog-title"
    className={cn("text-base font-semibold leading-snug text-foreground", className)}
    {...props}
  />
));
AlertDialogTitle.displayName = "AlertDialogTitle";

/** What happens if the reader confirms, in muted grey. */
const AlertDialogDescription = React.forwardRef<
  HTMLParagraphElement,
  WithClassName<AlertDialogPrimitive.Description.Props>
>(({ className, ...props }, ref) => (
  <AlertDialogPrimitive.Description
    ref={ref}
    data-slot="alert-dialog-description"
    className={cn("text-sm leading-relaxed text-muted-foreground", className)}
    {...props}
  />
));
AlertDialogDescription.displayName = "AlertDialogDescription";

/** The confirm button, in the oxblood face of the primary Button. */
const AlertDialogAction = React.forwardRef<
  HTMLButtonElement,
  WithClassName<AlertDialogPrimitive.Close.Props>
>(({ className, ...props }, ref) => (
  <AlertDialogPrimitive.Close
    ref={ref}
    data-slot="alert-dialog-action"
    className={cn(buttonVariants(), className)}
    {...props}
  />
));
AlertDialogAction.displayName = "AlertDialogAction";

/** The way out: the ruled toolbar tab beside the confirm button. */
const AlertDialogCancel = React.forwardRef<
  HTMLButtonElement,
  WithClassName<AlertDialogPrimitive.Close.Props>
>(({ className, ...props }, ref) => (
  <AlertDialogPrimitive.Close
    ref={ref}
    data-slot="alert-dialog-cancel"
    className={cn(buttonVariants({ variant: "secondary" }), className)}
    {...props}
  />
));
AlertDialogCancel.displayName = "AlertDialogCancel";

export {
  AlertDialog,
  AlertDialogPortal,
  AlertDialogOverlay,
  AlertDialogTrigger,
  AlertDialogContent,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogDescription,
  AlertDialogAction,
  AlertDialogCancel,
};
